import fs from'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
const specs={bank:{action:'set-bank',ref:'device:utility-1',bank:0},parameter:{action:'re-enable-automation',ref:'parameter:gain-1'},macro:{action:'re-enable-automation',ref:'parameter:macro-1'},comparison:{action:'save-comparison',ref:'device:utility-1'},insert:{action:'insert-chain',trackRef:'track:track-1',chainRef:'chain:rack-1:0',deviceName:'Utility'},'move-track':{action:'move-cross',ref:'device:moving',index:0,targetTrackRef:'track:track-2'},'move-chain':{action:'move-cross',ref:'device:moving',index:1,targetChainRef:'chain:rack-1:0'},'move-from-chain':{action:'move-cross',ref:'device:inside',index:0,targetTrackRef:'track:track-2'},chain:{chainRef:'chain:rack-1:0',colorIndex:9,autoColor:true,mute:true,solo:true}};const cases=[];
function clean(value){if(value===undefined)return null;value=structuredClone(value);if(value?.result?.content?.[0]?.text)try{value.result.content[0].text=JSON.parse(value.result.content[0].text)}catch{}function walk(v,key){if(typeof v==='string'&&/^(devadv|chainset)_/.test(v))return '$transaction';if(key==='expiresAt'&&v!==0)return '$time';if(Array.isArray(v))return v.map(w=>walk(w));if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,w])=>[k,walk(w,k)]));return v}return walk(value)}
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null}
async function make(kind,scenario,args=specs[kind],previewOnly=false){const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();let fault='',fired=false,after=false;const track=sim.state.tracks[0],device=track.devices[0];
 device.kind='rack';device.canHaveChains=true;device.chains=[{ref:'chain:rack-1:0',parentRef:device.ref,objectIdentity:'simulator:chain:rack-1:0',index:0,name:'Chain',mute:false,solo:false,colorIndex:5,autoColor:false,devices:[{ref:'device:inside',parentRef:'chain:rack-1:0',objectIdentity:'simulator:device:inside',name:'Utility',kind:'audio-effect',enabled:true,parameters:[]}]}];device.macros=[{ref:'parameter:macro-1',objectIdentity:'simulator:parameter:macro-1',name:'Macro',value:0.5}];track.devices.push({ref:'device:moving',parentRef:track.ref,objectIdentity:'simulator:device:moving',name:'Utility',kind:'audio-effect',enabled:true,parameters:[]});sim.state.tracks.push({ref:'track:track-2',objectIdentity:'simulator:track:track-2',name:'Target',kind:'midi',volume:0.85,pan:0,mute:false,solo:false,armed:false,clips:[],clipSlots:[],devices:[],sends:[]});
 const object=kind==='chain'?device.chains[0]:device;if(scenario==='missing-identity')delete object.objectIdentity;if(scenario==='missing-bank')delete device.parameterBank;if(scenario==='missing-comparison')delete device.comparison;
 function status(){const s=sim.status();if(scenario==='disconnected')s.connected=false;if(scenario==='no-capability')s.capabilities=[];if(scenario==='no-operation')s.operations=[];return s}
 function readFault(){if(!fired&&(fault.endsWith('current-read')||fault.endsWith('-read')&&after)){fired=true;throw Error('injected authoritative read failure')}}
 async function capture(method,args,ctx,work){const row={method,args:clean(args),context:clean(context(ctx))};calls.push(row);try{const value=await work();row.result=clean(value);return value}catch(error){row.error={message:error.message,kind:error instanceof LiveMutationNotDispatchedError?'not-dispatched':'error'};throw error}}
 function invoke(i,c){const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return structuredClone(cache.get(key));if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure')}if(!fired&&fault.endsWith('null')){fired=true;return null}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(result));after=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure')}if(!fired&&fault==='apply-invalid-identity'){fired=true;result.objectIdentity=''}return result}
 const adapter={status,snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>sim.invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),refreshStatusAsync:c=>capture('status',null,c,()=>status()),snapshotAsync:(c,r)=>capture('snapshot',r??null,c,()=>{readFault();return sim.snapshotAsync(c,r)}),discoverAsync:(r,c)=>capture('discover',r,c,()=>{readFault();return sim.discoverAsync(r,c)}),getAsync:(r,c)=>capture('get',r,c,()=>{readFault();return sim.get(r)}),invokeAsync:(i,c)=>capture('invoke',i,c,()=>invoke(i,c))};const host=new McpHost(adapter),steps=[],method=kind==='chain'?'Chain':'DeviceAdvanced';let txid;
 async function step(action,p,extra={}){const before=calls.length,input={action,args:clean(p),status:status(),...extra};let result;try{const signal=new AbortController();if(extra.abort)signal.abort();result=action==='undo'?await host.liveUndoAsync(1,{...p,transactionId:txid},signal.signal):await host['live'+method+(action==='preview'?'Preview':'Apply')+'Async'](1,action==='preview'?p:{...p,transactionId:txid},signal.signal)}catch(error){result={throw:error.message}}if(action==='preview')try{txid=JSON.parse(result.result.content[0].text).transactionId}catch{}steps.push({...input,result:clean(result),record:clean(txid?host.clipLifecycleTransactions.get(txid):undefined),calls:calls.slice(before)})}
 await step('preview',args);if(txid&&!previewOnly){const record=host.clipLifecycleTransactions.get(txid);if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity')object.objectIdentity='manual';if(scenario==='state'){if(kind==='chain')object.mute=true;else device.parameterBank=2}
 if(scenario.startsWith('apply-'))fault=scenario;for(const[index,key]of['apply-key','other-key','apply-key'].entries())await step('apply',{confirmation:'apply',idempotencyKey:key},{...(scenario==='expire'&&index===0?{expire:true}:{}),...(scenario==='apply-preabort'?{abort:true}:{})});fault='';fired=false;after=false;
 const made=sim.state.tracks.flatMap(t=>host.flattenDeviceRows(t.devices)).find(d=>d.ref===record.created?.ref);if(scenario==='undo-epoch')sim.reconnect();if(scenario==='undo-identity'){if(kind==='chain')object.objectIdentity='manual';else if(made)made.objectIdentity='manual'}if(scenario==='undo-owner-identity')track.objectIdentity='manual';if(scenario==='undo-state'){if(kind==='chain')object.mute=false;else if(made)made.name='Manual'}
 if(scenario.startsWith('undo-')&&!['undo-epoch','undo-identity','undo-owner-identity','undo-state'].includes(scenario))fault=scenario;for(const key of ['undo-key','other-undo-key','undo-key'])await step('undo',{confirmation:'undo',idempotencyKey:key});}
 cases.push({label:kind+' '+scenario,tool:kind==='chain'?'chain':'device_advanced',steps});}
const scenarios=['normal','expire','epoch','identity','state','missing-identity','missing-bank','missing-comparison','disconnected','no-capability','no-operation','apply-before','apply-after','apply-refusal','apply-no-effect','apply-null','apply-read','apply-current-read','apply-preabort','apply-invalid-identity','undo-before','undo-after','undo-refusal','undo-no-effect','undo-null','undo-read','undo-current-read','undo-epoch','undo-identity','undo-owner-identity','undo-state'];
for(const kind of Object.keys(specs)){for(const scenario of scenarios)await make(kind,scenario);const valid=specs[kind];for(const args of [null,[],{},false,0,'x',{...valid,extra:1}])await make(kind,'invalid '+JSON.stringify(args),args,true);for(const key of Object.keys(valid)){const omit={...valid};delete omit[key];await make(kind,'omitted '+key,omit,true);for(const value of [null,[],{},false,true,-1,0,0.5,2,99,'','a'.repeat(257)])await make(kind,'invalid '+key+' '+JSON.stringify(value),{...valid,[key]:value},true)}}
fs.writeFileSync(new URL('host-advanced-devices-oracle.json',import.meta.url),JSON.stringify({cases}));console.log({cases:cases.length,steps:cases.reduce((n,c)=>n+c.steps.length,0)});
